package com.projecteden.dataset;

import java.io.IOException;
import java.nio.file.*;
import java.util.*;

import org.springframework.stereotype.Component;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.projecteden.imagenormalization.ImageNormalizationService;
import com.projecteden.memorytaxonomy.observation.UploadedImagePayload;

@Component
@ConditionalOnProperty(prefix = "eden.dataset", name = "enabled", havingValue = "true")
public class FilesystemVisionDatasetManager implements VisionDatasetManager {
	private final DatasetPathResolver paths;
	private final ImageNormalizationService normalization;
	private final ObjectMapper json;
	public FilesystemVisionDatasetManager(ImageNormalizationService normalization, ObjectMapper json) { this(normalization, json, Path.of(System.getenv().getOrDefault("EDEN_DATASET_ROOT", System.getProperty("user.home") + "/.project-eden/datasets"))); }
	@Autowired
	FilesystemVisionDatasetManager(ImageNormalizationService normalization, ObjectMapper json, @Value("${eden.dataset.root:}") String configuredRoot) { this(normalization, json, configuredRoot == null || configuredRoot.isBlank() ? Path.of(System.getenv().getOrDefault("EDEN_DATASET_ROOT", System.getProperty("user.home") + "/.project-eden/datasets")) : Path.of(configuredRoot)); }
	FilesystemVisionDatasetManager(ImageNormalizationService normalization, ObjectMapper json, Path root) { this.normalization=normalization; this.json=new ObjectMapper(new YAMLFactory()).registerModule(new JavaTimeModule()).setSerializationInclusion(JsonInclude.Include.NON_NULL).enable(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS); this.paths=new DatasetPathResolver(root); }
	public VisionDataset createDataset(VisionDataset dataset) { Path dir=paths.dataset(dataset.id()); if(Files.exists(dir)) throw new IllegalArgumentException("DATASET_ALREADY_EXISTS"); try { Files.createDirectories(dir.resolve("cases")); write(dir.resolve("dataset.yml"), dataset); return dataset; } catch(IOException e){throw new IllegalStateException("METADATA_WRITE_FAILED",e);} }
	public Optional<VisionDataset> findDataset(VisionDatasetId id) { return read(paths.dataset(id).resolve("dataset.yml"), VisionDataset.class); }
	public List<VisionDataset> listDatasets() { Path base=paths.safe(Path.of("datasets")); if(!Files.isDirectory(base)) return List.of(); try(var stream=Files.list(base)){return stream.map(path->read(path.resolve("dataset.yml"),VisionDataset.class)).flatMap(Optional::stream).sorted(Comparator.comparing(d->d.id().value())).toList();}catch(IOException e){throw new IllegalStateException("METADATA_READ_FAILED",e);} }
	public VisionDatasetCase importCase(VisionDatasetId datasetId, VisionDatasetCase input, Path source) { if (Files.isSymbolicLink(source)) throw new IllegalArgumentException("SOURCE_SYMLINK_NOT_ALLOWED"); if(!input.consent().importAllowed()) throw new IllegalArgumentException("CONSENT_REQUIRED"); VisionDataset dataset=findDataset(datasetId).orElseThrow(()->new IllegalArgumentException("DATASET_NOT_FOUND")); Path target=paths.caseDirectory(datasetId,input.caseId()); if(Files.exists(target)) throw new IllegalArgumentException("CASE_ALREADY_EXISTS"); try { byte[] raw=Files.readAllBytes(source); var normalized=normalization.normalize(UploadedImagePayload.of("source", Files.probeContentType(source), raw.length, raw)); if(listCases(datasetId).stream().anyMatch(c->normalized.sha256().equals(c.sha256()))) throw new IllegalArgumentException("DUPLICATE_IMAGE"); Path temp=paths.safe(Path.of("temp", UUID.randomUUID().toString())); Files.createDirectories(temp); String file=normalized.contentType().equals("image/png")?"image.png":"image.jpg"; Files.write(temp.resolve(file),normalized.bytes(),StandardOpenOption.CREATE_NEW); VisionDatasetCase stored=new VisionDatasetCase("eden-dataset-schema-v1",input.caseId(),datasetId,"cases/"+input.caseId().value()+"/"+file,normalized.contentType(),normalized.width(),normalized.height(),normalized.sha256(),input.consent(),input.groundTruth(),input.reviewStatus(),"ACTIVE"); write(temp.resolve("case.yml"),stored); Files.move(temp,target,StandardCopyOption.ATOMIC_MOVE); write(paths.dataset(datasetId).resolve("dataset.yml"),new VisionDataset(dataset.schemaVersion(),dataset.id(),dataset.name(),dataset.version(),dataset.status(),dataset.caseCount()+1)); return stored; } catch(IOException e){throw new IllegalStateException("IMAGE_WRITE_FAILED",e);} }
	public Optional<VisionDatasetCase> findCase(VisionDatasetId d, VisionDatasetCaseId c){return read(paths.caseDirectory(d,c).resolve("case.yml"),VisionDatasetCase.class);} public List<VisionDatasetCase> listCases(VisionDatasetId d){Path p=paths.dataset(d).resolve("cases");if(!Files.isDirectory(p))return List.of();try(var s=Files.list(p)){return s.map(x->read(x.resolve("case.yml"),VisionDatasetCase.class)).flatMap(Optional::stream).sorted(Comparator.comparing(c->c.caseId().value())).toList();}catch(IOException e){throw new IllegalStateException(e);}}
	public VisionDatasetCase archiveCase(VisionDatasetId d,VisionDatasetCaseId c){VisionDatasetCase old=findCase(d,c).orElseThrow(()->new IllegalArgumentException("CASE_NOT_FOUND"));VisionDatasetCase archived=new VisionDatasetCase(old.schemaVersion(),old.caseId(),old.datasetId(),old.relativePath(),old.contentType(),old.width(),old.height(),old.sha256(),old.consent(),old.groundTruth(),old.reviewStatus(),"ARCHIVED");try{write(paths.caseDirectory(d,c).resolve("case.yml"),archived);return archived;}catch(IOException e){throw new IllegalStateException(e);}}
	public Path exportManifest(VisionDatasetId d){Path out=paths.dataset(d).resolve("manifests/evaluation-v2.yml");try{Files.createDirectories(out.getParent());List<Map<String,Object>> cases=listCases(d).stream().filter(c->!"ARCHIVED".equals(c.status())).map(c->manifestEntry(d,c)).flatMap(Optional::stream).toList();write(out,Map.of("version",2,"cases",cases));return out;}catch(IOException e){throw new IllegalStateException("MANIFEST_EXPORT_FAILED",e);}}
	private Optional<Map<String,Object>> manifestEntry(VisionDatasetId datasetId, VisionDatasetCase datasetCase) { Optional<ReviewItem> review = reviewForCase(datasetId, datasetCase.caseId()); if (review.isPresent()) { if (!review.get().publishesGroundTruth()) return Optional.empty(); return Optional.of(manifestEntry(datasetCase, review.get().groundTruth())); } if (!"CONFIRMED".equals(datasetCase.reviewStatus()) && !"CORRECTED".equals(datasetCase.reviewStatus())) return Optional.empty(); return Optional.of(manifestEntry(datasetCase, datasetCase.groundTruth())); }
	private Map<String,Object> manifestEntry(VisionDatasetCase datasetCase, VisionGroundTruth groundTruth) { Map<String,Object> entry=new LinkedHashMap<>(); entry.put("caseId",datasetCase.caseId().value()); entry.put("enabled",true); entry.put("imagePath","../"+datasetCase.relativePath()); entry.put("expectedPrimary",groundTruth.category()); entry.put("expectedSecondary",groundTruth.secondaryCategories()); entry.put("expectedTags",groundTruth.tags()); entry.put("expectedObjects",groundTruth.objects()); entry.put("expectedActivities",groundTruth.activities()); entry.put("expectedRelationships",groundTruth.relationships()); entry.put("expectedFallback",groundTruth.fallback()); return entry; }
	private Optional<ReviewItem> reviewForCase(VisionDatasetId datasetId, VisionDatasetCaseId caseId) { Path directory=paths.reviewDirectory(datasetId); if(!Files.isDirectory(directory)) return Optional.empty(); try(var reviews=Files.list(directory)){return reviews.filter(path->path.getFileName().toString().endsWith(".yml")).map(path->read(path,ReviewItem.class)).flatMap(Optional::stream).filter(review->review.caseId().equals(caseId)).findFirst();}catch(IOException exception){throw new IllegalStateException("REVIEW_READ_FAILED",exception);} }
	private <T> Optional<T> read(Path p,Class<T> t){if(!Files.exists(p))return Optional.empty();try{return Optional.of(json.readValue(p.toFile(),t));}catch(IOException e){throw new IllegalStateException("METADATA_READ_FAILED",e);}} private void write(Path p,Object o)throws IOException{Files.createDirectories(p.getParent());json.writerWithDefaultPrettyPrinter().writeValue(p.toFile(),o);}
}
